/* ============================================================
   GRAVITY LAB — interface system
   Dark, restrained scientific-laboratory HUD layered over WebGL.
   ============================================================ */

:root {
  --bg: #04070c;
  --bg-soft: #071019;
  --panel: rgba(8, 14, 21, 0.82);
  --panel-strong: rgba(6, 11, 17, 0.94);
  --line: rgba(122, 190, 230, 0.14);
  --line-strong: rgba(122, 210, 255, 0.3);
  --cyan: #57e8ff;
  --cyan-soft: #8df4ff;
  --cyan-dim: #1d8aa6;
  --blue: #2f7bff;
  --warn: #ffb27a;
  --text: #dceaf4;
  --text-soft: #a8c0d1;
  --muted: #688092;
  --muted-2: #4b6172;
  --mono: "Cascadia Mono", "SFMono-Regular", "Consolas", "Liberation Mono", monospace;
  --sans: "Segoe UI Variable", "Segoe UI", Inter, system-ui, -apple-system, sans-serif;
  --radius: 14px;
  --panel-shadow: 0 24px 70px rgba(0, 0, 0, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.035);
}

* {
  box-sizing: border-box;
}

html,
body {
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: var(--bg);
  color: var(--text);
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

#app {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
}

button {
  font: inherit;
  color: inherit;
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible,
input:focus-visible {
  outline: 1px solid var(--cyan);
  outline-offset: 2px;
}

::selection {
  background: rgba(87, 232, 255, 0.24);
  color: #ffffff;
}

.viewport {
  position: fixed;
  inset: 0;
  z-index: 0;
}

.viewport canvas,
.lab-canvas {
  display: block;
  width: 100%;
  height: 100%;
  cursor: grab;
}

.viewport canvas:active {
  cursor: grabbing;
}

.scene-vignette,
.scene-scanlines {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 2;
}

.scene-vignette {
  background:
    radial-gradient(ellipse at 50% 44%, transparent 24%, rgba(2, 5, 9, 0.34) 72%, rgba(2, 5, 9, 0.82) 100%),
    linear-gradient(to bottom, rgba(3, 6, 10, 0.62), transparent 17%, transparent 74%, rgba(3, 6, 10, 0.72));
}

.scene-scanlines {
  z-index: 3;
  opacity: 0.032;
  background: repeating-linear-gradient(
    to bottom,
    rgba(210, 245, 255, 0.7) 0,
    rgba(210, 245, 255, 0.7) 1px,
    transparent 1px,
    transparent 3px
  );
}

.hud-layer {
  z-index: 10;
}

.hud-layer[data-enter] {
  opacity: 0;
}

/* ------------------------------------------------------------
   Top bar
   ------------------------------------------------------------ */

.topbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: 74px;
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 0 22px;
  background: linear-gradient(to bottom, rgba(4, 8, 13, 0.94), rgba(4, 8, 13, 0.58) 72%, transparent);
  border-bottom: 1px solid rgba(120, 190, 230, 0.1);
  backdrop-filter: blur(10px);
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 248px;
}

.brand-mark {
  width: 40px;
  height: 40px;
  color: var(--cyan);
  filter: drop-shadow(0 0 12px rgba(87, 232, 255, 0.45));
}

.brand-mark svg {
  width: 100%;
  height: 100%;
  display: block;
}

.brand-text h1 {
  margin: 0;
  font-size: 18px;
  line-height: 1;
  font-weight: 620;
  letter-spacing: 0.2em;
  color: #f2fbff;
}

.brand-text h1 span {
  margin-left: 5px;
  font-weight: 300;
  color: var(--cyan);
}

.brand-text p {
  margin: 7px 0 0;
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.19em;
  color: var(--muted);
}

.topbar-center {
  display: flex;
  align-items: center;
  gap: 14px;
  margin: 0 auto;
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: 0.18em;
  color: #7893a6;
  white-space: nowrap;
}

.experiment-tag b {
  color: var(--cyan-soft);
  font-weight: 600;
}

.topbar-divider {
  width: 1px;
  height: 14px;
  background: rgba(120, 190, 230, 0.22);
}

.topbar-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
}

.status-chip,
.engine-chip {
  display: flex;
  align-items: center;
  gap: 7px;
  height: 30px;
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: rgba(7, 13, 20, 0.7);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.12em;
  color: var(--text-soft);
  white-space: nowrap;
}

.status-dot,
.engine-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--cyan);
  box-shadow: 0 0 8px var(--cyan);
}

.status-chip[data-state="live"] {
  border-color: rgba(87, 232, 255, 0.28);
  color: #bff6ff;
}

.status-chip[data-state="live"] .status-dot {
  animation: statusPulse 1.8s ease-in-out infinite;
}

.status-chip[data-state="paused"] {
  border-color: rgba(255, 178, 122, 0.32);
  color: #ffd8bd;
}

.status-chip[data-state="paused"] .status-dot {
  background: var(--warn);
  box-shadow: 0 0 8px var(--warn);
}

.status-chip[data-state="booting"] .status-dot,
.engine-chip[data-state="booting"] .engine-dot {
  background: var(--muted);
  box-shadow: none;
  animation: statusPulse 1.1s ease-in-out infinite;
}

.engine-chip[data-state="ready"] .engine-dot {
  background: #7dffcf;
  box-shadow: 0 0 8px #7dffcf;
}

.engine-chip[data-state="error"] {
  border-color: rgba(255, 120, 120, 0.4);
  color: #ffd2d2;
}

.engine-chip[data-state="error"] .engine-dot {
  background: #ff6b6b;
  box-shadow: 0 0 8px #ff6b6b;
}

.topbar-buttons {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-left: 4px;
}

.top-btn {
  height: 34px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 0 11px;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: rgba(10, 18, 27, 0.74);
  color: #b9d1e0;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.11em;
  cursor: pointer;
  transition: border-color 0.2s ease, background 0.2s ease, color 0.2s ease, transform 0.15s ease;
}

.top-btn .icon {
  width: 15px;
  height: 15px;
  flex: none;
}

.top-btn:hover {
  border-color: rgba(87, 232, 255, 0.38);
  background: rgba(16, 30, 42, 0.9);
  color: #ecfcff;
}

.top-btn:active {
  transform: translateY(1px);
}

.top-btn.primary-ghost {
  border-color: rgba(87, 232, 255, 0.28);
  color: #c9f8ff;
}

.top-btn.danger-ghost:hover {
  border-color: rgba(255, 178, 122, 0.42);
  color: #ffe5d2;
}

#btn-pause .icon-play {
  display: none;
}

#btn-pause[data-state="paused"] .icon-pause {
  display: none;
}

#btn-pause[data-state="paused"] .icon-play {
  display: block;
}

/* ------------------------------------------------------------
   Side panels
   ------------------------------------------------------------ */

.panel {
  position: fixed;
  top: 92px;
  bottom: 66px;
  width: 318px;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background:
    linear-gradient(165deg, rgba(13, 22, 32, 0.88), rgba(5, 10, 16, 0.92)),
    var(--panel);
  box-shadow: var(--panel-shadow);
  backdrop-filter: blur(20px) saturate(118%);
  overflow: hidden;
}

.panel::before {
  content: "";
  position: absolute;
  top: 0;
  left: 22px;
  right: 22px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(87, 232, 255, 0.55), transparent);
  z-index: 1;
}

.panel::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: var(--radius);
  pointer-events: none;
  box-shadow: inset 0 0 60px rgba(21, 105, 140, 0.045);
}

.panel-left {
  left: 20px;
}

.panel-right {
  right: 20px;
  width: 302px;
}

.panel-header {
  position: relative;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  padding: 17px 18px 14px;
  border-bottom: 1px solid rgba(120, 190, 230, 0.09);
  flex: none;
}

.eyebrow {
  display: block;
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.23em;
  color: rgba(87, 232, 255, 0.72);
}

.panel-header h2 {
  margin: 5px 0 0;
  font-size: 15px;
  font-weight: 580;
  letter-spacing: 0.035em;
  color: #e8f6ff;
}

.header-right {
  display: flex;
  align-items: center;
  gap: 9px;
}

.live-indicator {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.14em;
  color: var(--muted);
}

.live-indicator i {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--cyan);
  box-shadow: 0 0 6px var(--cyan);
  animation: statusPulse 1.8s ease-in-out infinite;
}

.panel-close {
  display: none;
  width: 26px;
  height: 26px;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: rgba(8, 14, 21, 0.7);
  color: var(--text-soft);
  cursor: pointer;
}

.panel-close svg {
  width: 14px;
  height: 14px;
}

.panel-scroll {
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 4px 18px 18px;
  scrollbar-width: thin;
  scrollbar-color: rgba(87, 232, 255, 0.24) transparent;
}

.panel-scroll::-webkit-scrollbar {
  width: 5px;
}

.panel-scroll::-webkit-scrollbar-thumb {
  background: rgba(87, 232, 255, 0.2);
  border-radius: 10px;
}

.panel-scroll::-webkit-scrollbar-track {
  background: transparent;
}

.control-group {
  padding: 15px 0 16px;
  border-bottom: 1px solid rgba(120, 190, 230, 0.075);
}

.control-group:first-child {
  padding-top: 12px;
}

.control-group:last-of-type {
  border-bottom: none;
}

.group-title {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 11px;
}

.group-index {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 19px;
  height: 17px;
  padding: 0 4px;
  border: 1px solid rgba(87, 232, 255, 0.2);
  border-radius: 4px;
  font-family: var(--mono);
  font-size: 7px;
  color: rgba(87, 232, 255, 0.8);
}

.group-title h3 {
  margin: 0;
  font-family: var(--mono);
  font-size: 8.5px;
  font-weight: 500;
  letter-spacing: 0.18em;
  color: #a9c4d6;
}

.group-meta {
  margin-left: auto;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.12em;
  color: var(--muted-2);
}

/* Body type selector */

.type-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 7px;
}

.type-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  padding: 10px 4px 8px;
  border: 1px solid rgba(112, 172, 210, 0.14);
  border-radius: 9px;
  background: rgba(7, 13, 20, 0.7);
  color: #7fa5bb;
  cursor: pointer;
  transition: border-color 0.2s ease, background 0.2s ease, color 0.2s ease, box-shadow 0.2s ease;
}

.type-card svg {
  width: 28px;
  height: 28px;
  margin-bottom: 2px;
}

.type-card span {
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.1em;
  color: #a7c2d3;
}

.type-card small {
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.08em;
  color: var(--muted-2);
}

.type-card:hover {
  border-color: rgba(87, 232, 255, 0.35);
  background: rgba(12, 24, 34, 0.8);
  color: #b9f6ff;
}

.type-card.is-active {
  border-color: rgba(87, 232, 255, 0.55);
  background: linear-gradient(160deg, rgba(24, 100, 124, 0.32), rgba(9, 26, 36, 0.62));
  color: var(--cyan);
  box-shadow: inset 0 0 22px rgba(55, 190, 220, 0.08), 0 0 18px rgba(23, 130, 160, 0.08);
}

.type-card.is-active span {
  color: #e5fcff;
}

.type-card.is-active small {
  color: rgba(87, 232, 255, 0.7);
}

/* Buttons */

.primary-btn,
.secondary-btn,
.ghost-btn {
  position: relative;
  width: 100%;
  min-height: 41px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 0 14px;
  border-radius: 8px;
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: 0.14em;
  cursor: pointer;
  transition: transform 0.16s ease, border-color 0.2s ease, background 0.2s ease, box-shadow 0.2s ease;
}

.primary-btn {
  margin-top: 11px;
  border: 1px solid rgba(87, 232, 255, 0.34);
  background: linear-gradient(135deg, rgba(28, 122, 150, 0.28), rgba(16, 55, 84, 0.3));
  color: #ddfbff;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.055), 0 8px 24px rgba(0, 0, 0, 0.22);
}

.primary-btn svg {
  width: 15px;
  height: 15px;
  flex: none;
}

.primary-btn em,
.secondary-btn em {
  position: absolute;
  right: 11px;
  font-style: normal;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.04em;
  color: rgba(169, 219, 234, 0.55);
}

.primary-btn:hover {
  border-color: rgba(87, 232, 255, 0.7);
  background: linear-gradient(135deg, rgba(37, 152, 184, 0.38), rgba(19, 68, 102, 0.4));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08), 0 0 24px rgba(40, 170, 200, 0.14);
  transform: translateY(-1px);
}

.primary-btn:active,
.secondary-btn:active,
.ghost-btn:active {
  transform: translateY(0);
}

.primary-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  transform: none;
}

.primary-btn.danger {
  border-color: rgba(255, 178, 122, 0.34);
  background: linear-gradient(135deg, rgba(137, 76, 38, 0.26), rgba(63, 34, 22, 0.3));
  color: #ffe9d9;
}

.primary-btn.danger:hover {
  border-color: rgba(255, 178, 122, 0.66);
  background: linear-gradient(135deg, rgba(163, 90, 44, 0.36), rgba(78, 41, 25, 0.4));
  box-shadow: 0 0 24px rgba(255, 150, 90, 0.12);
}

.primary-btn.compact {
  min-height: 34px;
  margin-top: 0;
  font-size: 7.5px;
}

.secondary-btn {
  border: 1px solid rgba(122, 190, 230, 0.18);
  background: rgba(9, 16, 24, 0.72);
  color: #b9d2e1;
}

.secondary-btn svg {
  width: 14px;
  height: 14px;
}

.secondary-btn:hover {
  border-color: rgba(87, 232, 255, 0.38);
  background: rgba(13, 25, 35, 0.85);
  color: #edfdff;
}

.ghost-btn {
  border: 1px dashed rgba(122, 190, 230, 0.16);
  background: transparent;
  color: var(--muted);
  min-height: 32px;
  font-size: 7.5px;
}

.ghost-btn:hover {
  border-color: rgba(87, 232, 255, 0.3);
  color: #bce8f3;
}

.hint {
  margin: 9px 0 0;
  font-size: 9.5px;
  line-height: 1.55;
  color: var(--muted);
}

/* Gravity + force controls */

.readout-row {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
}

.readout-row.compact {
  align-items: center;
}

.readout-label {
  display: block;
  font-family: var(--mono);
  font-size: 6.8px;
  letter-spacing: 0.16em;
  color: var(--muted-2);
}

.readout-value {
  display: flex;
  align-items: baseline;
  gap: 5px;
  margin-top: 3px;
}

.readout-value b {
  font-family: var(--mono);
  font-size: 26px;
  line-height: 1;
  font-weight: 500;
  letter-spacing: -0.02em;
  color: #eefdff;
  text-shadow: 0 0 22px rgba(87, 232, 255, 0.22);
  font-variant-numeric: tabular-nums;
}

.readout-value.small b {
  font-size: 21px;
}

.readout-value small {
  font-family: var(--mono);
  font-size: 8px;
  color: var(--muted);
}

.switch {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 0;
  border: none;
  background: none;
  cursor: pointer;
}

.switch-track {
  position: relative;
  width: 38px;
  height: 20px;
  border: 1px solid rgba(122, 190, 230, 0.25);
  border-radius: 20px;
  background: rgba(5, 10, 15, 0.85);
  transition: background 0.2s ease, border-color 0.2s ease;
}

.switch-thumb {
  position: absolute;
  top: 2px;
  left: 2px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: #668596;
  transition: transform 0.22s cubic-bezier(0.2, 0.8, 0.2, 1), background 0.2s ease, box-shadow 0.2s ease;
}

.switch[aria-checked="true"] .switch-track {
  border-color: rgba(87, 232, 255, 0.6);
  background: rgba(16, 86, 104, 0.5);
}

.switch[aria-checked="true"] .switch-thumb {
  transform: translateX(18px);
  background: var(--cyan);
  box-shadow: 0 0 10px rgba(87, 232, 255, 0.7);
}

.switch-label {
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.12em;
  color: var(--muted);
}

.switch[aria-checked="true"] .switch-label {
  color: var(--cyan);
}

.range-block {
  margin-top: 12px;
}

.range-input {
  --fill: 40%;
  --accent: var(--cyan);
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 18px;
  margin: 0;
  padding: 0;
  background: transparent;
  cursor: pointer;
}

.range-input.warm {
  --accent: var(--warn);
}

.range-input::-webkit-slider-runnable-track {
  height: 3px;
  border-radius: 4px;
  background: linear-gradient(
    to right,
    var(--accent) 0,
    var(--accent) var(--fill),
    rgba(112, 162, 190, 0.18) var(--fill),
    rgba(112, 162, 190, 0.18) 100%
  );
}

.range-input::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 13px;
  height: 13px;
  margin-top: -5px;
  border: 2px solid #061018;
  border-radius: 50%;
  background: #e9fcff;
  box-shadow: 0 0 0 3px rgba(87, 232, 255, 0.12), 0 0 14px rgba(87, 232, 255, 0.45);
}

.range-input.warm::-webkit-slider-thumb {
  box-shadow: 0 0 0 3px rgba(255, 178, 122, 0.12), 0 0 14px rgba(255, 178, 122, 0.45);
}

.range-input::-moz-range-track {
  height: 3px;
  border-radius: 4px;
  background: rgba(112, 162, 190, 0.18);
}

.range-input::-moz-range-progress {
  height: 3px;
  border-radius: 4px;
  background: var(--accent);
}

.range-input::-moz-range-thumb {
  width: 13px;
  height: 13px;
  border: 2px solid #061018;
  border-radius: 50%;
  background: #e9fcff;
}

.range-scale {
  display: flex;
  justify-content: space-between;
  margin-top: 2px;
  font-family: var(--mono);
  font-size: 6.5px;
  color: var(--muted-2);
}

.preset-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 5px;
  margin-top: 9px;
}

.preset-row button {
  height: 25px;
  border: 1px solid rgba(112, 172, 210, 0.13);
  border-radius: 5px;
  background: rgba(7, 13, 20, 0.6);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.07em;
  cursor: pointer;
  transition: border-color 0.18s ease, color 0.18s ease, background 0.18s ease;
}

.preset-row button:hover {
  border-color: rgba(87, 232, 255, 0.34);
  color: #c8f7ff;
}

.preset-row button.is-active {
  border-color: rgba(87, 232, 255, 0.48);
  background: rgba(20, 82, 100, 0.3);
  color: #c9f9ff;
}

.slider-badge {
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.08em;
  color: var(--muted);
  padding: 3px 6px;
  border: 1px solid var(--line);
  border-radius: 4px;
  white-space: nowrap;
}

.actions-group {
  display: flex;
  flex-direction: column;
  gap: 7px;
  padding-bottom: 10px;
}

.shortcut-note {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 10px;
  padding-top: 12px;
  border-top: 1px solid rgba(120, 190, 230, 0.07);
  font-family: var(--mono);
  font-size: 6.5px;
  color: var(--muted-2);
}

kbd {
  display: inline-block;
  padding: 2px 4px;
  border: 1px solid rgba(122, 190, 230, 0.18);
  border-bottom-color: rgba(122, 190, 230, 0.3);
  border-radius: 3px;
  background: rgba(11, 20, 29, 0.8);
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.06em;
  color: #9eb9ca;
}

/* ------------------------------------------------------------
   Telemetry
   ------------------------------------------------------------ */

.telemetry-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1px;
  margin-top: 12px;
  border: 1px solid rgba(120, 190, 230, 0.1);
  border-radius: 10px;
  overflow: hidden;
  background: rgba(120, 190, 230, 0.08);
}

.stat-cell {
  padding: 10px 11px;
  background: rgba(6, 11, 17, 0.92);
  min-width: 0;
  transition: background 0.3s ease;
}

.stat-cell.wide {
  grid-column: span 2;
}

.stat-cell.pulse {
  animation: cellPulse 0.55s ease-out;
}

.stat-label {
  display: block;
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.15em;
  color: var(--muted-2);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.stat-cell strong {
  display: block;
  margin: 5px 0 3px;
  font-family: var(--mono);
  font-size: 20px;
  line-height: 1;
  font-weight: 500;
  letter-spacing: -0.02em;
  color: #e7fbff;
  font-variant-numeric: tabular-nums;
}

.stat-cell strong small {
  margin-left: 3px;
  font-size: 7.5px;
  letter-spacing: 0.04em;
  color: var(--muted);
}

.stat-foot {
  display: block;
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.06em;
  color: var(--muted-2);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.spark-panel,
.selection-panel {
  margin-top: 12px;
  padding: 11px;
  border: 1px solid rgba(120, 190, 230, 0.1);
  border-radius: 10px;
  background: rgba(6, 11, 17, 0.72);
}

.spark-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.spark-value {
  font-family: var(--mono);
  font-size: 7px;
  color: var(--muted);
}

.spark-value i {
  font-style: normal;
  color: var(--cyan-soft);
}

#speed-sparkline {
  display: block;
  width: 100%;
  height: 56px;
  margin-top: 7px;
}

.spark-axis {
  display: flex;
  justify-content: space-between;
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.08em;
  color: var(--muted-2);
}

.selection-hint {
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.1em;
  color: var(--muted-2);
}

.selection-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 14px 10px 8px;
}

.reticle {
  position: relative;
  width: 34px;
  height: 34px;
  margin-bottom: 8px;
  border: 1px dashed rgba(87, 232, 255, 0.25);
  border-radius: 50%;
}

.reticle::before,
.reticle::after {
  content: "";
  position: absolute;
  background: rgba(87, 232, 255, 0.4);
}

.reticle::before {
  top: 50%;
  left: 7px;
  right: 7px;
  height: 1px;
}

.reticle::after {
  left: 50%;
  top: 7px;
  bottom: 7px;
  width: 1px;
}

.reticle span {
  position: absolute;
  inset: 10px;
  border: 1px solid rgba(87, 232, 255, 0.5);
  border-radius: 50%;
}

.selection-empty p {
  margin: 0 0 4px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.12em;
  color: #a5c2d3;
}

.selection-empty small {
  max-width: 190px;
  font-size: 8.5px;
  line-height: 1.5;
  color: var(--muted);
}

.selection-details {
  padding-top: 10px;
}

.selection-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.selection-title b {
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.08em;
  color: #dffbff;
}

.badge {
  padding: 2px 6px;
  border: 1px solid rgba(87, 232, 255, 0.28);
  border-radius: 3px;
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.1em;
  color: var(--cyan);
}

.selection-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px 8px;
  margin-top: 9px;
  padding: 9px 0;
  border-top: 1px solid rgba(120, 190, 230, 0.08);
  border-bottom: 1px solid rgba(120, 190, 230, 0.08);
}

.selection-grid div:last-child {
  grid-column: span 2;
}

.selection-grid span {
  display: block;
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.1em;
  color: var(--muted-2);
}

.selection-grid b {
  display: block;
  margin-top: 2px;
  font-family: var(--mono);
  font-size: 8.5px;
  font-weight: 400;
  color: #bcd8e6;
}

.selection-actions {
  display: flex;
  gap: 6px;
  margin-top: 9px;
}

.selection-actions .primary-btn {
  flex: 1;
}

.ghost-icon-btn {
  width: 34px;
  height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: rgba(8, 14, 21, 0.7);
  color: var(--muted);
  cursor: pointer;
}

.ghost-icon-btn svg {
  width: 13px;
  height: 13px;
}

.ghost-icon-btn:hover {
  border-color: rgba(87, 232, 255, 0.35);
  color: var(--cyan-soft);
}

.engine-readout {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid rgba(120, 190, 230, 0.08);
}

.engine-readout div {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.engine-readout span {
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.12em;
  color: var(--muted-2);
}

.engine-readout b {
  font-family: var(--mono);
  font-size: 6.5px;
  font-weight: 400;
  letter-spacing: 0.02em;
  color: #8198a8;
  text-align: right;
}

/* ------------------------------------------------------------
   Bottom bar / overlays
   ------------------------------------------------------------ */

.hintbar {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 0 24px;
  background: linear-gradient(to top, rgba(4, 7, 12, 0.9), transparent);
  font-family: var(--mono);
  font-size: 6.8px;
  letter-spacing: 0.1em;
  color: #5c7284;
  pointer-events: none;
}

.camera-hints {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 16px;
}

.camera-hints span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.sector-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
  color: #567083;
}

.sector-tag i {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--cyan);
  box-shadow: 0 0 6px var(--cyan);
}

.mobile-dock {
  display: none;
}

.panel-backdrop {
  position: fixed;
  inset: 0;
  z-index: 25;
  background: rgba(2, 5, 9, 0.62);
  backdrop-filter: blur(4px);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.3s ease, visibility 0.3s ease;
}

.panel-backdrop.is-visible {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}

.toast {
  position: fixed;
  left: 50%;
  bottom: 64px;
  z-index: 60;
  transform: translate(-50%, 8px);
  max-width: min(90vw, 460px);
  padding: 9px 15px;
  border: 1px solid rgba(87, 232, 255, 0.3);
  border-radius: 7px;
  background: rgba(6, 14, 21, 0.94);
  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.05);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.08em;
  line-height: 1.5;
  color: #c9f7ff;
  text-align: center;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.toast[data-tone="warn"] {
  border-color: rgba(255, 178, 122, 0.38);
  color: #ffe3cd;
}

.flash-layer {
  position: fixed;
  inset: 0;
  z-index: 5;
  pointer-events: none;
  opacity: 0;
  background: radial-gradient(circle at 50% 48%, rgba(160, 246, 255, 0.6), rgba(30, 120, 190, 0.16) 42%, transparent 68%);
  mix-blend-mode: screen;
}

/* Boot screen */

.boot-screen {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background:
    radial-gradient(circle at 50% 44%, rgba(10, 35, 48, 0.75), transparent 45%),
    radial-gradient(circle at 50% 50%, #061018 0%, #03060a 66%);
}

.boot-core {
  position: relative;
  width: 132px;
  height: 132px;
  margin-bottom: 26px;
}

.orbit {
  position: absolute;
  inset: 0;
  border: 1px solid rgba(87, 232, 255, 0.22);
  border-radius: 50%;
}

.orbit-a {
  transform: rotate(24deg) scaleY(0.38);
  animation: orbitSpin 9s linear infinite;
}

.orbit-b {
  transform: rotate(-38deg) scaleY(0.38);
  border-color: rgba(47, 123, 255, 0.3);
  animation: orbitSpinReverse 12s linear infinite;
}

.orbit-c {
  inset: 22px;
  border-color: rgba(87, 232, 255, 0.16);
  border-style: dashed;
  animation: orbitSpin 18s linear infinite;
}

.boot-core .core {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 12px;
  height: 12px;
  margin: -6px 0 0 -6px;
  border-radius: 50%;
  background: #d8fbff;
  box-shadow: 0 0 14px 4px rgba(87, 232, 255, 0.55), 0 0 60px 12px rgba(47, 123, 255, 0.22);
  animation: corePulse 2s ease-in-out infinite;
}

.boot-screen h2 {
  margin: 0;
  font-size: 24px;
  font-weight: 600;
  letter-spacing: 0.34em;
  color: #f1fdff;
  text-shadow: 0 0 34px rgba(87, 232, 255, 0.24);
}

.boot-screen h2 span {
  font-weight: 300;
  color: var(--cyan);
}

.boot-sub {
  margin: 9px 0 0;
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.32em;
  color: var(--muted);
}

.boot-progress {
  position: relative;
  width: 220px;
  height: 2px;
  margin-top: 28px;
  overflow: hidden;
  background: rgba(120, 190, 230, 0.13);
  border-radius: 2px;
}

.boot-progress span {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 38%;
  background: linear-gradient(90deg, transparent, var(--cyan), transparent);
  animation: bootSweep 1.5s ease-in-out infinite;
}

.boot-status {
  margin: 13px 0 0;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.18em;
  color: rgba(87, 232, 255, 0.7);
}

.boot-meta {
  margin: 28px 0 0;
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.24em;
  color: var(--muted-2);
}

.fatal-screen {
  position: fixed;
  inset: 0;
  z-index: 110;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: rgba(3, 6, 10, 0.94);
  backdrop-filter: blur(10px);
}

.fatal-screen[hidden] {
  display: none;
}

.fatal-card {
  width: min(480px, 100%);
  padding: 28px;
  border: 1px solid rgba(255, 120, 120, 0.28);
  border-radius: 12px;
  background: linear-gradient(160deg, rgba(28, 13, 15, 0.7), rgba(7, 11, 16, 0.96));
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.6);
}

.fatal-card .eyebrow {
  color: rgba(255, 140, 140, 0.8);
}

.fatal-card h2 {
  margin: 8px 0 10px;
  font-size: 20px;
  font-weight: 560;
}

.fatal-card p {
  margin: 0 0 10px;
  font-size: 12px;
  line-height: 1.6;
  color: var(--text-soft);
}

.fatal-card pre {
  max-height: 130px;
  margin: 0 0 16px;
  padding: 10px;
  overflow: auto;
  border: 1px solid rgba(255, 120, 120, 0.16);
  border-radius: 6px;
  background: rgba(0, 0, 0, 0.35);
  font-family: var(--mono);
  font-size: 8px;
  line-height: 1.5;
  color: #ffb8b8;
  white-space: pre-wrap;
}

.fatal-card .primary-btn {
  margin-top: 0;
}

/* Animations */

@keyframes statusPulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.35;
  }
}

@keyframes cellPulse {
  0% {
    background: rgba(31, 120, 145, 0.35);
  }
  100% {
    background: rgba(6, 11, 17, 0.92);
  }
}

@keyframes bootSweep {
  0% {
    left: -40%;
  }
  100% {
    left: 100%;
  }
}

@keyframes orbitSpin {
  from {
    transform: rotate(0deg) scaleY(0.38);
  }
  to {
    transform: rotate(360deg) scaleY(0.38);
  }
}

@keyframes orbitSpinReverse {
  from {
    transform: rotate(360deg) scaleY(0.38);
  }
  to {
    transform: rotate(0deg) scaleY(0.38);
  }
}

@keyframes corePulse {
  0%,
  100% {
    transform: scale(1);
    opacity: 1;
  }
  50% {
    transform: scale(0.7);
    opacity: 0.65;
  }
}

/* ------------------------------------------------------------
   Responsive layout
   ------------------------------------------------------------ */

@media (max-width: 1280px) {
  .topbar-center {
    display: none;
  }

  .panel-left {
    width: 300px;
  }

  .panel-right {
    width: 286px;
  }
}

@media (max-width: 1080px) {
  .brand {
    min-width: 0;
  }

  .engine-chip {
    display: none;
  }

  .panel-left {
    width: 286px;
  }

  .panel-right {
    width: 272px;
  }
}

@media (max-width: 980px) {
  .topbar {
    height: 62px;
    padding: 0 14px;
    gap: 10px;
  }

  .brand-mark {
    width: 32px;
    height: 32px;
  }

  .brand-text h1 {
    font-size: 15px;
    letter-spacing: 0.16em;
  }

  .brand-text p {
    display: none;
  }

  .status-chip {
    height: 27px;
    padding: 0 8px;
    font-size: 7px;
  }

  .topbar-buttons {
    gap: 4px;
  }

  .top-btn {
    width: 34px;
    padding: 0;
    justify-content: center;
  }

  .top-btn span {
    display: none;
  }

  .panel {
    top: auto;
    bottom: 76px;
    left: 12px;
    right: 12px;
    width: auto;
    max-height: min(66vh, 560px);
    visibility: hidden;
    transform: translateY(calc(100% + 100px));
    transition: transform 0.42s cubic-bezier(0.2, 0.8, 0.2, 1), visibility 0.42s;
    z-index: 30;
  }

  .panel.is-open {
    visibility: visible;
    transform: translateY(0);
  }

  .panel-left,
  .panel-right {
    width: auto;
  }

  .panel-close {
    display: inline-flex;
  }

  .panel-scroll {
    padding-bottom: 16px;
  }

  .mobile-dock {
    position: fixed;
    left: 50%;
    bottom: 12px;
    z-index: 35;
    display: flex;
    gap: 6px;
    padding: 4px;
    transform: translateX(-50%);
    border: 1px solid var(--line);
    border-radius: 10px;
    background: rgba(6, 12, 18, 0.9);
    box-shadow: 0 14px 40px rgba(0, 0, 0, 0.45);
    backdrop-filter: blur(16px);
  }

  .mobile-dock button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    width: 104px;
    height: 36px;
    border: 1px solid transparent;
    border-radius: 7px;
    background: transparent;
    color: #a8c4d4;
    font-family: var(--mono);
    font-size: 8px;
    letter-spacing: 0.12em;
    cursor: pointer;
  }

  .mobile-dock button svg {
    width: 14px;
    height: 14px;
  }

  .mobile-dock button.is-active {
    border-color: rgba(87, 232, 255, 0.3);
    background: rgba(20, 82, 100, 0.28);
    color: #d8fbff;
  }

  .hintbar {
    display: none;
  }

  .toast {
    bottom: 72px;
  }

  .scene-vignette {
    background:
      radial-gradient(ellipse at 50% 44%, transparent 30%, rgba(2, 5, 9, 0.4) 78%, rgba(2, 5, 9, 0.8) 100%),
      linear-gradient(to bottom, rgba(3, 6, 10, 0.7), transparent 20%, transparent 72%, rgba(3, 6, 10, 0.85));
  }
}

@media (max-width: 620px) {
  .topbar {
    height: 56px;
    padding: 0 10px;
  }

  .brand {
    gap: 8px;
  }

  .brand-mark {
    width: 28px;
    height: 28px;
  }

  .brand-text h1 {
    font-size: 13px;
    letter-spacing: 0.13em;
  }

  .brand-text h1 span {
    margin-left: 3px;
  }

  .status-chip {
    padding: 0 7px;
    font-size: 6.5px;
    letter-spacing: 0.06em;
  }

  .top-btn {
    width: 31px;
    height: 31px;
  }

  .top-btn .icon {
    width: 14px;
    height: 14px;
  }

  .panel {
    bottom: 70px;
    left: 8px;
    right: 8px;
    max-height: 68vh;
    border-radius: 12px;
  }

  .panel-header {
    padding: 14px 14px 12px;
  }

  .panel-scroll {
    padding: 2px 14px 14px;
  }

  .mobile-dock {
    bottom: 9px;
  }

  .mobile-dock button {
    width: 96px;
    height: 34px;
  }

  .toast {
    bottom: 64px;
    font-size: 7.5px;
  }

  .readout-value b {
    font-size: 23px;
  }

  .telemetry-grid {
    margin-top: 10px;
  }

  .stat-cell {
    padding: 9px 10px;
  }

  .stat-cell strong {
    font-size: 18px;
  }

  .stat-cell.wide {
    grid-column: span 2;
  }
}

@media (max-width: 400px) {
  .brand-text h1 {
    font-size: 12px;
  }

  .status-chip span:last-child {
    display: none;
  }

  .status-chip {
    width: 24px;
    justify-content: center;
    padding: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
